pub(crate) fn write_coedge(out: &mut Vec<u8>, c: &BrepCoedge) {
    write_str_lp(out, &c.id);
    write_str_lp(out, &c.edge);
    write_bool(out, c.forward);
    match &c.pcurve {
        Some(curve) => {
            write_bool(out, true);
            write_curve2(out, curve);
        }
        None => write_bool(out, false),
