    out.extend_from_slice(&c.prange.0.to_le_bytes());
    out.extend_from_slice(&c.prange.1.to_le_bytes());
    write_str_lp(out, &c.loop_id);
    write_str_lp(out, &c.next);
    write_str_lp(out, &c.prev);
}

