    let mut tokens: Vec<String> = Vec::new();
    if let Some(l) = &d.layers {
        tokens.push(format!("layers={}", enc_named_triple(l, |k: &String| enc_str(k), enc_layer_diff, enc_layer)));
    }
    if let Some(b) = &d.blocks {
