            DocBlockDiff::Heading(DocHeadingDiff { level: hd.level.map(|_| *level), style_id: hd.style_id.as_ref().map(|_| style_id.clone()), runs: hd.runs.as_ref().map(|rd| inverse_indexed(runs, rd, inverse_run)) })
