        "schema={}\nspatial=[{}]\nelements=[{}]\nrelations=[{}]",
        enc_str(&s.schema),
        s.spatial.iter().map(enc_spatial_node).collect::<Vec<_>>().join(","),
        s.elements.iter().map(enc_element).collect::<Vec<_>>().join(","),
        s.relations.iter().map(enc_relation).collect::<Vec<_>>().join(","),
