        SlideShape::TextBox { frame, blocks } => {
            out.push(0);
            write_frame(out, frame);
            write_blocks(out, blocks);
        }
        SlideShape::Picture { frame, image } => {
            out.push(1);
            write_frame(out, frame);
            write_image(out, image);
