        return Ok(SemioVideoDiff::default());
    }
    let rest = line.strip_prefix("streams=").ok_or_else(|| format!("semio video diff: unknown token {line:?}"))?;
    Ok(SemioVideoDiff { streams: Some(dec_streams_diff(rest)?) })
}

