            rows = dec_list(rest, dec_row)?;
        } else {
            return Err(format!("semio table snapshot: unknown line {line:?}"));
        }
    }
    Ok(SemioTableSnapshot { schema: schema.ok_or_else(|| "semio table snapshot: missing schema line".to_string())?, columns, rows })
}

