        BrepCurve2::Nurbs { control_points, weights, degree, knots } => format!("N[{},{},{},{}]", enc_list(control_points, enc_point2), enc_list(weights, |w: &f64| NativeF64(*w).to_string()), degree, enc_list(knots, |k: &f64| NativeF64(*k).to_string()),),
